// Web Push notifications to the owner's devices (phone and PC) without third-party libraries.
// Pushes are sent WITHOUT a payload — so no message encryption is needed: the panel's service worker receives an
// empty «tickle», asks the server what is new (/api/admin/notify) and shows the notification itself.
// Authorisation is VAPID: an ES256-signed JWT + the public key (keys are generated by setup.mjs).
import { createPrivateKey, createPublicKey, generateKeyPairSync, sign } from 'node:crypto';

const b64u = (buf) => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

/** new VAPID key pair: public key as uncompressed point (base64url, what the browser needs), private as JWK «d» */
export const generateVapid = () => {
  const { publicKey, privateKey } = generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
  const pub = publicKey.export({ format: 'jwk' });
  const priv = privateKey.export({ format: 'jwk' });
  const point = Buffer.concat([Buffer.from([4]), Buffer.from(pub.x, 'base64url'), Buffer.from(pub.y, 'base64url')]);
  return { publicKey: b64u(point), privateKey: priv.d };
};

const keyFrom = (publicKey, privateD) => {
  const point = Buffer.from(publicKey, 'base64url');
  const jwk = { kty: 'EC', crv: 'P-256', x: b64u(point.subarray(1, 33)), y: b64u(point.subarray(33, 65)), d: privateD };
  return createPrivateKey({ key: jwk, format: 'jwk' });
};

/** JWT for one push service (audience = its origin), valid 12 h */
export const vapidJwt = ({ publicKey, privateKey, subject }, audience, now = Date.now()) => {
  const header = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  const claims = b64u(JSON.stringify({ aud: audience, exp: Math.floor(now / 1000) + 12 * 3600, sub: subject }));
  const data = `${header}.${claims}`;
  const sig = sign('sha256', Buffer.from(data), { key: keyFrom(publicKey, privateKey), dsaEncoding: 'ieee-p1363' });
  return `${data}.${b64u(sig)}`;
};

/** for tests: the public key object of a VAPID pair */
export const vapidPublicKeyObject = (publicKey) => {
  const point = Buffer.from(publicKey, 'base64url');
  return createPublicKey({ key: { kty: 'EC', crv: 'P-256', x: b64u(point.subarray(1, 33)), y: b64u(point.subarray(33, 65)) }, format: 'jwk' });
};

/**
 * Sends an empty push to every subscription; drops subscriptions the push service says are gone (404/410).
 * @param {{ vapid: { publicKey: string, privateKey: string, subject: string }, store: import('./store.mjs').Store, fetch?: typeof fetch, log?: (s: string) => void }} o
 */
export const pushAll = async ({ vapid, store, fetch: f = globalThis.fetch, log = console.log }) => {
  if (!vapid?.publicKey || !vapid?.privateKey) return 0;
  const subs = store.pushSubs();
  if (!subs.length) return 0;
  const keep = [];
  let sent = 0;
  await Promise.all(
    subs.map(async (s) => {
      try {
        const aud = new URL(s.endpoint).origin;
        const r = await f(s.endpoint, {
          method: 'POST',
          headers: { TTL: '86400', Urgency: 'high', Authorization: `vapid t=${vapidJwt(vapid, aud)}, k=${vapid.publicKey}`, 'Content-Length': '0' },
        });
        if (r.status === 404 || r.status === 410) return; // unsubscribed / expired — forget it
        keep.push(s);
        if (r.ok) sent++;
        else log(`push ${r.status} for ${aud}`);
      } catch (e) {
        keep.push(s);
        log(`push failed: ${e.message}`);
      }
    }),
  );
  if (keep.length !== subs.length) store.setPushSubs(keep);
  return sent;
};
